        if (!currentOptionContext[optionName]) continue;
        if (normalizeText(getOptionValue(variant, optionIndex)) !== normalizeText(currentOptionContext[optionName])) {
          return;
        }
        continue;
      }

      if (includeAllAxes) continue; // per-card filters handle Color/etc
      if (!currentOptionContext[optionName]) continue;
      if (normalizeText(getOptionValue(variant, optionIndex)) !== normalizeText(currentOptionContext[optionName])) {
        return;
      }
    }

	    var roleInfo = getRoleInfoForVariant(variant, productData.options, sizeOptionIndex);
	    if (!roleInfo) return;
	    var typeValue = getTypeOptionValue(variant, productData.options, sizeOptionIndex);
	    var groupKey = getRoleGroupKey(roleInfo, typeValue, { noSplitByType: skipTypeFilter });

	    if (!roleGroups[groupKey]) {
	      roleGroups[groupKey] = {
	        key: groupKey,
	        roleKey: roleInfo.key,
	        label: roleInfo.label,
	        helper: localizeTypeLabel(typeValue),
	        helperRaw: typeValue,
	        options: [],
	      };
	    }

	    // Capture every non-size axis value (Color, Pattern, Style, …)
	    // per variant so the bundle's per-card picker can build a
	    // swatch/pill row for each axis with OOS combos disabled.
	    //
	    // Type is normally excluded because the global Type picker
	    // handles it. But when Type is implicit (Pattern A/B in
	    // detectImplicitTypeMapping → skipTypeFilter is true) the
	    // global picker is hidden and Type needs to live INSIDE each
	    // card as a pill row — same pattern as Color on Picnic Plaid.
	    // For Pattern A products (e.g. Picnic Plaid: mother↔Dress,
	    // father↔Shirt) Type ends up as a 1-value axis per card and is
	    // auto-suppressed by the renderer's `values.length <= 1` gate.
	    // For Pattern B products (e.g. Blue Check: father has both
	    // Shirt + Shorts) the Type pill row genuinely renders and lets
	    // the shopper pick the garment for THAT family member without
	    // affecting other cards. That's the behavior Frank wants per
	    // May 12 2026 PDP review.
	    var nonSizeAxes = {};
	    for (var ai = 0; ai < productData.options.length; ai += 1) {
	      if (ai === sizeOptionIndex) continue;
	      var axisName = productData.options[ai].name;
	      if (!axisName) continue;
	      if (!skipTypeFilter && isTypeLikeLabel(normalizeText(axisName))) continue;
	      var axisVal = getOptionValue(variant, ai);
	      if (axisVal) nonSizeAxes[axisName] = axisVal;
	    }

	    roleGroups[groupKey].options.push({
	      id: String(variant.id),
	      sizeLabel: localizeSizeLabel(roleInfo.sizeLabel, roleInfo.key),
	      fullLabel: roleInfo.fullLabel,
	      price: Number(variant.price) || 0,
	      available: variant.available !== false,
	      axes: nonSizeAxes,
	    });
  });

  return Object.keys(roleGroups)
    .map(function (key) {
      return roleGroups[key];
    })
	    .sort(function (first, second) {
	      var roleSort = getRoleOrder(first.roleKey || first.key) - getRoleOrder(second.roleKey || second.key);
	      if (roleSort !== 0) return roleSort;
	      return String(first.helperRaw || '').localeCompare(String(second.helperRaw || ''));
	    });
}

function getRoleHelperLabel(variant, options, sizeOptionIndex) {
  return localizeTypeLabel(getTypeOptionValue(variant, options, sizeOptionIndex));
}

function getMatchingSetSelections(builder) {
  // Returns { groupKey: variantId } map for whichever instance cards
  // currently have a selected pill. Used to preserve user choices when
  // the main <variant-selects> fires "change". With the instance model
  // (May 11 2026 rev), per-card state is held in the closure's
  // `instances` array — this function exists for back-compat with the
  // outer change handler but most preservation is already automatic.
  var selections = {};
  builder.querySelectorAll('[data-instance-card]').forEach(function (card) {
    var groupKey = card.getAttribute('data-role-card');
    var selectedPill = card.querySelector('[data-instance-pill].is-selected');
    if (!groupKey || !selectedPill) return;
    // Last write wins — if two cards of the same group both have
    // selections, the second one overrides. That's fine for the outer
    // change handler because the instance model itself isn't reset.
    selections[groupKey] = String(selectedPill.getAttribute('data-variant-id') || '');
  });
  return selections;
}

function getMatchingSetOptionLabel(group, option) {
  var parts = [group && group.label, group && group.helper, option && option.sizeLabel].filter(Boolean);
  return parts.join(' ');
}

function needsNativeVariantPicker(productData) {
  var options = productData && productData.options;
  var variants = productData && productData.variants;
  var sizeOptionIndex = findSizeOptionIndex(options);
  if (sizeOptionIndex < 0 || !Array.isArray(variants) || !variants.length) return true;
  // Keep every source size reachable, including height and qualified adult labels.
  // A partial custom builder must not silently omit variants it cannot classify.
  return variants.some(function (variant) {
    return !getRoleInfoForVariant(variant, options, sizeOptionIndex);
  });
}

function initMatchingSetBuilder(wrapper, sectionId, productData) {
  var builder = wrapper.querySelector('[data-matching-set-builder]');
  if (!builder) return;

  // ─────────────────────────────────────────────────────────────────────
  // CRITICAL: normalize productData.options ordering by .position.
  // The Liquid template iterates product.options_with_values which is
  // not guaranteed to be position-sorted. Our buildRoleGroups +
  // getOptionValue use ARRAY INDEX (assumes index+1 = variant.option{N}),
  // so an unordered array causes wrong field lookups (size column
  // returning a color value, etc.). Sort once on init.
  // ─────────────────────────────────────────────────────────────────────
  if (productData && Array.isArray(productData.options)) {
    var sortedOptions = productData.options.slice().sort(function (a, b) {
      var pa = Number(a && a.position) || 0;
      var pb = Number(b && b.position) || 0;
      return pa - pb;
    });
    // Only swap if order actually differs to avoid breaking referential
    // equality where it isn't needed.
    var needsSort = sortedOptions.some(function (opt, idx) {
      return opt !== productData.options[idx];
    });
    if (needsSort) {
      productData = Object.assign({}, productData, { options: sortedOptions });
    }
  }

  if (needsNativeVariantPicker(productData)) {
    var nativeRoot = wrapper.closest('.product__info-container');
    builder.setAttribute('hidden', 'hidden');
    if (nativeRoot) {
      nativeRoot.classList.remove('product__info-container--matching-set');
      nativeRoot.setAttribute('data-has-matching-set', 'false');
      nativeRoot.setAttribute('data-matching-set-fallback', 'true');
      nativeRoot.removeAttribute('data-type-implicit');
    }
    document.dispatchEvent(new CustomEvent('dlm:matching-set-fallback', {
      detail: { sectionId: sectionId },
    }));
    return;
  }

  // CRO redesign May 2026: on bundle products the legacy "Compare
  // family sizes" details element (rendered by product-variant-picker.liquid)
  // sits at the same DOM level as the variant picker we hide via CSS,
  // but without the `hidden` attribute it stays visible and adds an
  // empty disclosure above the bundle. Mark it hidden so it doesn't
  // paint by default; the per-card "Find {role}'s fit" path now opens
  // a focused inline chart instead of expanding the full shared chart.
  var infoContainer = wrapper.closest('.product__info-container--matching-set');
  if (infoContainer) {
    var legacyGuide = document.querySelector('[data-matching-size-guide]');
    if (legacyGuide && !legacyGuide.hasAttribute('hidden')) {
      legacyGuide.setAttribute('hidden', 'hidden');
    }
  }

  var roleGrid = builder.querySelector('[data-matching-set-roles]');
  var matchingSetSummary = builder.querySelector('[data-matching-set-summary]');
  var chips = builder.querySelector('[data-matching-set-chips]');
  var total = builder.querySelector('[data-matching-set-total]');
  var emptyCopy = builder.querySelector('[data-matching-set-empty-copy]');
  var status = builder.querySelector('[data-matching-set-status]');
  var addButton = builder.querySelector('[data-matching-set-add-button]');
  var variantSelects = document.getElementById('variant-selects-' + sectionId);
  var productForm = document.getElementById('product-form-' + sectionId);
  var selectedVariantInput = productForm ? productForm.querySelector('[name="id"]') : null;
  var currency = productData.currency || 'USD';

  // ─────────────────────────────────────────────────────────────────────
  // CRO redesign May 2026 — INSTANCE MODEL (rev 2, May 11).
  //
  // The first rev keyed selections by role (one Mother card, one Child
  // card, period). That broke real family use cases — moms with two
  // daughters in different sizes, or a mom who wants two matching
  // outfits for herself + a friend, couldn't add them.
  //
  // Current model: `instances` is an ORDERED ARRAY of cards. Each card
  // is one independent line item. The same role can appear N times
  // with different sizes/qty. Default state shows one empty Mother
  // card + one empty Child card; + Add buttons always create a NEW
  // instance (never reuses an existing one); × removes that specific
  // instance.
  //
  //   instances = [
  //     { instanceId, roleKey, groupKey, variantId, quantity },
  //     ...
  //   ]
  //
  // ─────────────────────────────────────────────────────────────────────
  var instances = [];
  var instanceCounter = 0;
  var roleGroupsCache = [];
  var currentGroupKey = '';
  var bootstrapComplete = false;
  // Tracks the last Type axis value seen (e.g. "shirt" / "dress").
  // When the global Type picker changes, the bundle resets its
  // default-visible cards. null sentinel = first render — don't reset.
  var lastTypeContext = null;

  // Implicit-Type detection: when each Type value maps to a disjoint
  // set of roles (e.g. Dress↔mother/girl, Shirt↔father/boy), the
  // global Type picker becomes redundant and we treat Type as an
  // implied per-role attribute. See detectImplicitTypeMapping().
  var typeMapping = detectImplicitTypeMapping(productData);
  var typeIsImplicit = !!(typeMapping && typeMapping.implicit);
  // When Type is implicit we also instruct the surrounding CSS to hide
  // the global Type picker. The body class is read by the bundle's
  // CSS selectors.
  if (typeIsImplicit) {
    try {
      var bundleRoot = wrapper.closest('.product__info-container--matching-set');
      if (bundleRoot) bundleRoot.setAttribute('data-type-implicit', 'true');
    } catch (_e) { /* defensive */ }
  }

  // Per-bundle persistent size panel state.
  //   unitSystem      'metric' | 'imperial' — shared with the legacy
  //                   size-guide unit toggle via localStorage so the
  //                   shopper's preference rides across reloads and
  //                   between the panel + the full size chart.
  //   closedPanels    instanceIds the shopper has X-dismissed; cleared
  //                   when they pick a different size on that card so
  //                   the panel re-opens with fresh info.
  var BUNDLE_UNIT_STORAGE_KEY = 'dlm_size_chart_unit_system';
  var unitSystem = (function () {
    try {
      var stored = window.localStorage && window.localStorage.getItem(BUNDLE_UNIT_STORAGE_KEY);
      if (stored === 'imperial' || stored === 'metric') return stored;
    } catch (e) { /* localStorage may be blocked; default to metric */ }
    return 'metric';
  })();
  var closedPanels = Object.create(null);

  function setUnitSystem(next) {
    if (next !== 'metric' && next !== 'imperial') return;
    if (next === unitSystem) return;
    unitSystem = next;
    try {
      if (window.localStorage) window.localStorage.setItem(BUNDLE_UNIT_STORAGE_KEY, next);
    } catch (e) { /* ignore */ }
    renderBuilder();
  }

  function closeOpenSizePanels() {
    var changed = false;
    for (var i = 0; i < instances.length; i += 1) {
      var inst = instances[i];
      if (!inst || !inst.sizeLabel || closedPanels[inst.instanceId]) continue;
      closedPanels[inst.instanceId] = true;
      changed = true;
    }
    return changed;
  }

  function isMobileSizePanelViewport() {
    if (typeof window === 'undefined') return false;
    return !window.matchMedia || window.matchMedia('(max-width: 749px)').matches;
  }

  // ─────────────────────────────────────────────────────────────────────
  // Size-measurements lookup, populated lazily on first card render.
  // Source: every size-chart table in the product copy. Multi-role
  // listings often split Dress vs Shirt tables or put Mom/Dad/Girl/Boy
  // measurements in header groups, so the lookup keeps role/table context
  // instead of treating the first chart row as globally correct.
  // ─────────────────────────────────────────────────────────────────────
  var sizeMeasurementsByLabel = null;

  function normalizeSizeKey(text) {
    return String(text || '').toLowerCase().replace(/\s+/g, ' ').trim();
  }

  function makeSizeMeasurementLookup() {
    return {
      byLabel: Object.create(null),
      byRoleLabel: Object.create(null),
      byRoleGarmentLabel: Object.create(null),
      entries: [],
    };
  }

  function makeMeasurementEntryKey(roleKey, garmentKey, label) {
    return [roleKey || '', garmentKey || '', normalizeSizeKey(label)].join('::');
  }

  function getMeasurementRoleKeysFromText(text) {
    var normalizedText = normalizeText(text);
    if (!normalizedText) return [];

    var roles = [];
    ROLE_DEFINITIONS.forEach(function (roleDefinition) {
      var aliases = getRoleAliasCandidates(roleDefinition);
      var matched = aliases.some(function (alias) {
        var normalizedAlias = normalizeText(alias);
        if (!normalizedAlias || normalizedAlias.length < 3) return false;
        if (/^[a-z0-9]+$/.test(normalizedAlias)) {
          var aliasPattern = new RegExp('(^|[^a-z0-9])' + escapeRegExp(normalizedAlias) + '([^a-z0-9]|$)', 'i');
          return aliasPattern.test(normalizedText);
        }
        return normalizedText.indexOf(normalizedAlias) !== -1;
      });

      if (matched && roles.indexOf(roleDefinition.key) === -1) roles.push(roleDefinition.key);
    });

    return roles;
  }

  function getSizeMeasurementTableContextText(table) {
    if (!table) return '';

    var context = [];
    if (table.id) context.push(table.id);

    var previous = table.previousElementSibling;
    while (previous) {
      if (/^H[1-6]$/i.test(previous.tagName)) {
        context.push(cellText(previous));
        break;
      }
      if (/^TABLE$/i.test(previous.tagName)) break;
      previous = previous.previousElementSibling;
    }

    return context.join(' ');
  }

  function comparableSizeTokens(value) {
    var parsedRole = parseRoleFromSizeLabel(value);
    var text = normalizeText((parsedRole && parsedRole.sizeLabel) || value)
      .replace(/[\u2013\u2014]/g, '-')
      .replace(/(\d{1,2})\s*m(?=\/|\b|$)/gi, '$1m');
    var tokens = {};

    function add(token) {
      if (token) tokens[token] = true;
    }

    add(text);

    var adult = text.match(/\b(xxxxl|xxxl|xxl|[2-9]xl|xl|xs|s|m|l)\b/i);
    if (adult) {
      var adultToken = adult[1].toLowerCase();
      adultToken = { xxl: '2xl', xxxl: '3xl', xxxxl: '4xl' }[adultToken] || adultToken;
      add('adult:' + adultToken);
    }

    var month = text.match(/(?:^|[^0-9])(\d{1,2})\s*m(?:onths?)?(?=\/|\b|$)/i);
    if (month) {
      var monthValue = Number(month[1]);
      add('month:' + monthValue + 'm');
      if (monthValue && monthValue % 12 === 0) {
        var yearFromMonth = monthValue / 12;
        add('age-max:' + yearFromMonth);
        add('toddler:' + yearFromMonth + 't');
      }
    }

    var toddler = text.match(/(?:^|[^0-9])(\d{1,2})\s*t(?=\/|\b|$)/i);
    if (toddler) {
      var toddlerValue = Number(toddler[1]);
      if (toddlerValue) {
        add('toddler:' + toddlerValue + 't');
        add('age-max:' + toddlerValue);
        add('age-range:' + Math.max(1, toddlerValue - 1) + '-' + toddlerValue);
      }
    }

    var ageRange = text.match(
      /(?:^|[^0-9])(\d{1,2})\s*-\s*(\d{1,2})\s*(?:t|y|yr|yrs|year|years|ano|anos|año|años|an|ans|jahr|jahre|anni|anno|jaar|år|lat|lata|ani|let)?(?=\b|$)/i
    );
    if (ageRange) {
      var ageMin = Number(ageRange[1]);
      var ageMax = Number(ageRange[2]);
      if (ageMin > 0 && ageMin <= ageMax && ageMax <= 20) {
        add('age-min:' + ageMin);
        add('age-max:' + ageMax);
        add('age-range:' + ageMin + '-' + ageMax);
        add('toddler:' + ageMax + 't');
      }
    }

    var singleAge = text.match(
      /(?:^|[^0-9])(\d{1,2})\s*(?:t|y|yr|yrs|year|years|ano|anos|año|años|an|ans|jahr|jahre|anni|anno|jaar|år|lat|lata|ani|let)(?=\b|$)/i
    );
    if (singleAge) {
      var ageValue = Number(singleAge[1]);
      if (ageValue > 0 && ageValue <= 20) {
        add('age-min:' + ageValue);
        add('age-max:' + ageValue);
        add('toddler:' + ageValue + 't');
      }
    }

    var height = text.match(/(?:^|[^0-9])(\d{2,3})(?:\s*cm)?(?=\b|$)/i);
    if (height && Number(height[1]) >= 80) add('height-max:' + Number(height[1]));

    var numbers = text.match(/\d+(?:[.,]\d+)?/g);
    if (numbers && numbers.length) {
      add(
        'n:' +
          numbers
            .map(function (number) {
              return number.replace(',', '.').replace(/\.0+$/, '').replace(/(\.\d*?)0+$/, '$1');
            })
            .join('-')
      );
    }

    return Object.keys(tokens);
  }

  function mergeComparableSizeTokens(values) {
    var merged = {};
    (values || []).forEach(function (value) {
      comparableSizeTokens(value).forEach(function (token) {
        merged[token] = true;
      });
    });
    return Object.keys(merged);
  }

  function adultSizeRank(token) {
    var ranks = { xs: 1, s: 2, m: 3, l: 4, xl: 5, '2xl': 6, '3xl': 7, '4xl': 8 };
    return Object.prototype.hasOwnProperty.call(ranks, token) ? ranks[token] : null;
  }

  function numericTokenValues(tokens, prefix) {
    return (tokens || [])
      .filter(function (token) {
        return token.indexOf(prefix) === 0;
      })
      .map(function (token) {
        return Number(token.slice(prefix.length).replace(/[tm]$/, ''));
      })
      .filter(function (value) {
        return !Number.isNaN(value);
      });
  }

  function sizeTokenMatchRank(selectedTokens, rowTokens) {
    var selected = selectedTokens || [];
    var row = rowTokens || [];
    var selectedLookup = {};
    for (var i = 0; i < selected.length; i += 1) selectedLookup[selected[i]] = true;
    for (var j = 0; j < row.length; j += 1) {
      if (selectedLookup[row[j]]) return 1;
    }

    var selectedAdults = selected.filter(function (token) { return token.indexOf('adult:') === 0; });
    var rowAdults = row.filter(function (token) { return token.indexOf('adult:') === 0; });
    if (selectedAdults.length || rowAdults.length) {
      var selectedAdultRanks = selectedAdults
        .map(function (token) { return adultSizeRank(token.split(':', 2)[1]); })
        .filter(function (rank) { return rank !== null; });
      var rowAdultRanks = rowAdults
        .map(function (token) { return adultSizeRank(token.split(':', 2)[1]); })
        .filter(function (rank) { return rank !== null; });
      if (!selectedAdultRanks.length || !rowAdultRanks.length) return 0;
      return selectedAdultRanks.some(function (selectedRank) {
        return rowAdultRanks.some(function (rowRank) {
          return Math.abs(selectedRank - rowRank) <= 2;
        });
      })
        ? 2
        : 0;
    }

    var selectedAges = numericTokenValues(selected, 'age-max:').concat(numericTokenValues(selected, 'toddler:'));
    var rowAges = numericTokenValues(row, 'age-max:').concat(numericTokenValues(row, 'toddler:'));
    if (
      selectedAges.length &&
      rowAges.length &&
      selectedAges.some(function (selectedAge) {
        return rowAges.some(function (rowAge) {
          return Math.abs(selectedAge - rowAge) <= 2;
        });
      })
    ) {
      return 2;
    }

    var selectedHeights = numericTokenValues(selected, 'height-max:');
    var rowHeights = numericTokenValues(row, 'height-max:');
    if (
      selectedHeights.length &&
      rowHeights.length &&
      selectedHeights.some(function (selectedHeight) {
        return rowHeights.some(function (rowHeight) {
          return Math.abs(selectedHeight - rowHeight) <= 10;
        });
      })
    ) {
      return 2;
    }

    return 0;
  }

  function roleKeysCompatible(selectedRoleKey, entryRoleKey) {
    if (!selectedRoleKey || !entryRoleKey || selectedRoleKey === entryRoleKey) return true;
    if (selectedRoleKey === 'child' && ['girl', 'boy', 'baby'].indexOf(entryRoleKey) !== -1) return true;
    if (selectedRoleKey === 'adult' && ['mother', 'father'].indexOf(entryRoleKey) !== -1) return true;
    if (entryRoleKey === 'child' && ['girl', 'boy', 'baby'].indexOf(selectedRoleKey) !== -1) return true;
    if (entryRoleKey === 'adult' && ['mother', 'father'].indexOf(selectedRoleKey) !== -1) return true;
    return false;
  }

  function garmentKeysCompatible(selectedGarmentKey, entryGarmentKey) {
    if (!selectedGarmentKey || !entryGarmentKey || selectedGarmentKey === entryGarmentKey) return true;
    var shirtFamily = ['shirt', 'shorts', 'shirtShortsSet'];
    return shirtFamily.indexOf(selectedGarmentKey) !== -1 && shirtFamily.indexOf(entryGarmentKey) !== -1;
  }

  function inferBaseRoleKeyFromMeasurementSize(sizeLabel) {
    var parsed = parseRoleFromSizeLabel(sizeLabel);
    if (parsed) return parsed.key;

    var tokens = comparableSizeTokens(sizeLabel);
    if (tokens.some(function (token) { return token.indexOf('adult:') === 0; })) return 'adult';
    if (
      tokens.some(function (token) {
        return (
          token.indexOf('age-min:') === 0 ||
          token.indexOf('age-max:') === 0 ||
          token.indexOf('toddler:') === 0 ||
          token.indexOf('month:') === 0 ||
          token.indexOf('height-max:') === 0
        );
      })
    ) {
      return 'child';
    }
    return '';
  }

  function headerGarmentKeys(header) {
    if (!header) return [];
    if (typeof header === 'object') return getGarmentKeys([header.raw, header.label].filter(Boolean).join(' '));
    return getGarmentKeys(header);
  }

  function headerMatchesGarment(header, garmentKey) {
    if (!garmentKey) return true;
    var headerKeys = headerGarmentKeys(header);
    if (!headerKeys.length) return true;
    return headerKeys.some(function (headerKey) {
      return garmentKeysCompatible(garmentKey, headerKey);
    });
  }

  function getMeasurementGarmentKeysFromHeaders(headers) {
    var seen = Object.create(null);
    var keys = [];
    (headers || []).forEach(function (header, index) {
      if (index === 0) return;
      headerGarmentKeys(header).forEach(function (key) {
        if (!key || seen[key]) return;
        seen[key] = true;
        keys.push(key);
      });
    });
    return keys;
  }

  function pruneMeasurementsForRole(roleKey, headers, row, garmentKey) {
    if (!headers || !row || !row.length) return null;
    var hasRoleColumns = headers.some(function (header, index) {
      return index > 0 && !!parseRoleFromHeader(header);
    });
    var hasGarmentHeaders = !!garmentKey && headers.some(function (header, index) {
      return index > 0 && headerGarmentKeys(header).length > 0;
    });

    var keepIndexes = headers
      .map(function (_header, index) {
        return index;
      })
      .filter(function (index) {
        if (index === 0) return true;
        if (isGuideEmptyValue(row[index])) return false;
        if (hasGarmentHeaders && !headerGarmentKeys(headers[index]).length && !isSharedFitMeasurementHeader(headers[index])) return false;
        if (!headerMatchesGarment(headers[index], garmentKey)) return false;
        if (!hasRoleColumns) return true;
        var headerRole = parseRoleFromHeader(headers[index]);
        return !headerRole || roleKeysCompatible(roleKey, headerRole.key);
      });

    if (keepIndexes.length <= 1) return null;

    var pruned = pruneGuideGroupColumns(
      keepIndexes.map(function (index) {
        return headers[index];
      }),
      [
        keepIndexes.map(function (index) {
          return row[index];
        }),
      ]
    );

    if (!pruned.rows.length || !pruned.rows[0].slice(1).some(function (value) { return !isGuideEmptyValue(value); })) {
      return null;
    }

    return {
      headers: pruned.headers,
      row: pruned.rows[0],
    };
  }

  function addSizeMeasurementEntry(lookup, roleKey, garmentKey, label, headers, row) {
    var labelKey = normalizeSizeKey(label);
    if (!labelKey || !headers || !row || !row.length) return;
    if (!row.slice(1).some(function (value) { return !isGuideEmptyValue(value); })) return;

    var entry = {
      roleKey: roleKey || '',
      garmentKey: garmentKey || '',
      labelKey: labelKey,
      sizeTokens: comparableSizeTokens(label),
      headers: headers,
      row: row,
    };

    lookup.entries.push(entry);

    if (entry.roleKey && entry.garmentKey) {
