      '<dl class="product-matching-set__measurement-list">' +
      pairs
        .map(function (pair) {
          return (
            '<div class="product-matching-set__measurement-row">' +
            '<dt>' +
            escapeHtml(pair.label) +
            '</dt>' +
            '<dd>' +
            escapeHtml(pair.value) +
            '</dd>' +
            '</div>'
