    if (localizedSingleAgeMatch) {
      var localizedAgeValue = parseInt(localizedSingleAgeMatch[1], 10);
      if (!isNaN(localizedAgeValue)) {
        if (comparable.ageMax === null) comparable.ageMax = localizedAgeValue;
